import type { ColumnModel, FunctionModel, Model } from "./model.ts";

import { byCodePoint } from "../compare.ts";
import { block, indent, nullable, pascal, prop, q } from "./shared.ts";

export const GENERATED_HEADER =
  "// @generated by better-supabase gen. Do not edit; run `better-supabase gen` instead.";

function rowEntries(
  columns: readonly ColumnModel[],
  name: "app" | "db",
): string[] {
  return columns.map(
    (column) =>
      `${prop(column[name])}: ${nullable(column.tsType, column.nullable)};`,
  );
}

function insertEntries(
  columns: readonly ColumnModel[],
  name: "app" | "db",
): string[] {
  return columns.map((column) => {
    if (!column.insertable) return `${prop(column[name])}?: never;`;
    const optional = column.optional ? "?" : "";
    return `${prop(column[name])}${optional}: ${nullable(column.tsType, column.nullable)};`;
  });
}

function updateEntries(
  columns: readonly ColumnModel[],
  name: "app" | "db",
): string[] {
  return columns.map((column) => {
    if (!column.updatable) return `${prop(column[name])}?: never;`;
    return `${prop(column[name])}?: ${nullable(column.tsType, column.nullable)};`;
  });
}

/** Postgres passes `null` to any argument, so every argument accepts it. */
function argEntries(fn: FunctionModel): string[] {
  return fn.args.map(
    (arg) =>
      `${prop(arg.name)}${arg.optional ? "?" : ""}: ${nullable(arg.tsType, true)};`,
  );
}

function enrichedDatabase(model: Model): string[] {
  const schemas = model.config.schemas.flatMap((schema) => {
    const tables = model.tables
      .filter((t) => t.snapshot.schema === schema)
      .flatMap((table) => {
        const overrides = table.columns
          .filter(
            (column) =>
              (column.values !== undefined && !column.snapshot.isEnum) ||
              (column.json && column.tsType !== "Json") ||
              column.storage !== undefined,
          )
          .map((column) => `${prop(column.db)}: ${column.tsType};`);
        return overrides.length > 0
          ? block(prop(table.snapshot.name), overrides)
          : [];
      });
    return tables.length > 0 ? block(prop(schema), tables) : [];
  });
  if (schemas.length === 0) return ["export type Database = SupabaseDatabase;"];
  return [
    "export type Database = EnrichDatabase<",
    "  SupabaseDatabase,",
    "  {",
    ...indent(schemas, 2),
    "  }",
    ">;",
  ];
}

function modelsType(model: Model): string[] {
  const entries = model.tables.flatMap((table) => {
    const relations = table.relations.map(
      (relation) =>
        `${prop(relation.name)}: { table: ${q(relation.meta.table)}; kind: ${q(relation.meta.kind)}; nullable: ${String(relation.meta.nullable)} };`,
    );
    const pk = table.meta.primaryKey;
    const uniques = Object.entries(table.meta.uniqueKeys).map(
      ([name, columns]) =>
        `${prop(name)}: readonly [${columns.map(q).join(", ")}];`,
    );
    const flags: string[] = [];
    const tableFlags = table.meta.flags;
    if (tableFlags.softDelete)
      flags.push(`softDelete: ${q(tableFlags.softDelete)};`);
    if (tableFlags.timestamps) flags.push("timestamps: true;");
    if (tableFlags.tenant) flags.push(`tenant: ${q(tableFlags.tenant)};`);
    if (tableFlags.actor) flags.push("actor: true;");
    const none = "Record<never, never>";
    const union = (names: readonly string[]): string =>
      names.length === 0 ? "never" : names.map(q).join(" | ");
    return block(prop(table.key), [
      ...block("Row", rowEntries(table.columns, "app"), none),
      ...(table.snapshot.insertable
        ? block("Insert", insertEntries(table.columns, "app"), none)
        : ["Insert: never;"]),
      ...(table.snapshot.updatable
        ? block("Update", updateEntries(table.columns, "app"), none)
        : ["Update: never;"]),
      ...block("Relations", relations, none),
      `PrimaryKey: ${union(pk)};`,
      ...block("UniqueKeys", uniques, none),
      `Checks: ${union(table.snapshot.checks.map((check) => check.name))};`,
      `ForeignKeys: ${union(table.snapshot.foreignKeys.map((fk) => fk.name))};`,
      ...block("Flags", flags, none),
    ]);
  });
  return ["export type Models = {", ...indent(entries, 1), "};"];
}

function functionsType(model: Model): string[] {
  if (model.functions.length === 0)
    return ["export type Functions = Record<never, never>;"];
  const entries = model.functions.flatMap((fn) =>
    block(prop(fn.key), [
      ...block("Args", argEntries(fn), "Record<never, never>"),
      `Returns: ${fn.returns};`,
    ]),
  );
  return ["export type Functions = {", ...indent(entries, 1), "};"];
}

export interface EmitOptions {
  /** Import path from the generated module to `better-supabase`. */
  readonly runtimeImport?: string;
  /** Import path from the generated module to `database.types.ts`. */
  readonly databaseTypesImport?: string;
  /** Import path for each JSON type import, keyed by the configured path. */
  readonly importPathFor: (from: string) => string;
  /** Import path from the generated module to the metadata module (`emitMeta`). */
  readonly metaImport?: string;
}

/** The metadata module next to `generated.ts`: `generated.meta.js` and its `.d.ts`. */
export function metaPaths(output: string): { js: string; dts: string } {
  const base = output.replace(/\.[cm]?[jt]sx?$/, "");
  return { js: `${base}.meta.js`, dts: `${base}.meta.d.ts` };
}

/**
 * JSON with one line per table, function and other named entry, so the
 * module stays small to load and a schema change still diffs per entry.
 */
function compactJson(meta: Readonly<Record<string, unknown>>): string {
  const entries = Object.entries(meta).map(([key, value]) => {
    const name = JSON.stringify(key);
    if (typeof value !== "object" || value === null || Array.isArray(value))
      return `  ${name}: ${JSON.stringify(value)}`;
    const inner = Object.entries(value).map(
      ([entry, item]) =>
        `    ${JSON.stringify(entry)}: ${JSON.stringify(item)}`,
    );
    return inner.length === 0
      ? `  ${name}: {}`
      : `  ${name}: {\n${inner.join(",\n")}\n  }`;
  });
  return `{\n${entries.join(",\n")}\n}`;
}

/**
 * The schema metadata as plain JavaScript plus a one-line declaration, so
 * TypeScript reads `SchemaMeta` instead of checking thousands of lines of
 * object literal in every program that imports the generated module.
 */
export function emitMeta(
  model: Model,
  options: Pick<EmitOptions, "runtimeImport"> & {
    readonly types?: string;
  } = {},
): { js: string; dts: string } {
  const runtime = options.runtimeImport ?? "better-supabase";
  return {
    js: [
      GENERATED_HEADER,
      // Deno does not pick up a sibling .d.ts without this pragma.
      `// @ts-self-types="${options.types ?? "./generated.meta.d.ts"}"`,
      "/* oxlint-disable */",
      "/* eslint-disable */",
      "",
      `export default ${compactJson({ ...model.meta })};`,
      "",
    ].join("\n"),
    dts: [
      GENERATED_HEADER,
      "/* oxlint-disable */",
      "/* eslint-disable */",
      "",
      `import type { SchemaMeta } from ${q(runtime)};`,
      "",
      "declare const meta: SchemaMeta;",
      "export default meta;",
      "",
    ].join("\n"),
  };
}

/** Renders the generated module. */
export function emitModule(model: Model, options: EmitOptions): string {
  const runtime = options.runtimeImport ?? "better-supabase";
  const lines: string[] = [
    GENERATED_HEADER,
    "/* oxlint-disable */",
    "/* eslint-disable */",
    "",
    `import { defineSchema, type Schema } from ${q(runtime)};`,
  ];

  const storagePaths = model.tables.some((table) =>
    table.columns.some((column) => column.storage !== undefined),
  );
  lines.push(
    `import type { EnrichDatabase, MutableWhere, OrderByArg${storagePaths ? ", StoragePath" : ""} } from ${q(runtime)};`,
    `import type { Database as SupabaseDatabase } from ${q(options.databaseTypesImport ?? "./database.types.ts")};`,
  );
  const byFile = new Map<string, string[]>();
  for (const entry of model.jsonImports) {
    const list = byFile.get(entry.from) ?? [];
    list.push(entry.name);
    byFile.set(entry.from, list);
  }
  for (const [from, names] of [...byFile.entries()].sort(([a], [b]) =>
    byCodePoint(a, b),
  )) {
    lines.push(
      `import type { ${names.sort().join(", ")} } from ${q(options.importPathFor(from))};`,
    );
  }
  lines.push(
    `import meta from ${q(options.metaImport ?? "./generated.meta.js")};`,
    "",
    "export type Json = string | number | boolean | null | { [key: string]: Json | undefined } | Json[];",
    "",
    ...enrichedDatabase(model),
    "",
  );

  for (const entry of model.enums) {
    lines.push(
      `export const ${entry.constant} = [${entry.values.map(q).join(", ")}] as const;`,
      `export type ${pascal(entry.name)} = (typeof ${entry.constant})[number];`,
    );
  }
  for (const table of model.tables) {
    for (const column of table.columns) {
      if (column.values && !column.snapshot.isEnum) {
        const constant = `${table.key}${pascal(column.app)}Values`.replace(
          /^[A-Z]/,
          (c) => c.toLowerCase(),
        );
        lines.push(
          `export const ${constant} = [${column.values.map(q).join(", ")}] as const;`,
          `export type ${pascal(table.key)}${pascal(column.app)} = (typeof ${constant})[number];`,
        );
      }
    }
  }
  if (model.enums.length > 0) lines.push("");

  lines.push(
    ...modelsType(model),
    "",
    ...functionsType(model),
    "",
    "export type TableName = keyof Models;",
    "/** Constraint names for `isConflict`, `isCheck` and `isForeignKey`. */",
    "export type UniqueConstraint = { [T in TableName]: Extract<keyof Models[T]['UniqueKeys'], string> }[TableName];",
    "export type CheckConstraint = Models[TableName]['Checks'];",
    "export type ForeignKeyConstraint = Models[TableName]['ForeignKeys'];",
    "export type RowOf<T extends TableName> = Models[T]['Row'];",
    "export type InsertOf<T extends TableName> = Models[T]['Insert'];",
    "export type UpdateOf<T extends TableName> = Models[T]['Update'];",
    "/** A `where` for `T` you can assign to one key at a time. */",
    "export type WhereOf<T extends TableName> = MutableWhere<Models, T>;",
    "/** An `orderBy` for `T`: one sort or a list, by column or to-one relation. */",
    "export type OrderByOf<T extends TableName> = OrderByArg<Models, T>;",
    "",
  );
  if (model.meta.buckets) {
    lines.push(
      "/** Bucket configs for `defineBucket` from `better-supabase/storage`. */",
      `export const buckets = ${JSON.stringify(model.meta.buckets, null, 2)} as const;`,
      "",
    );
  }
  if (model.meta.topics) {
    lines.push(
      "/** Topic templates for `defineTopic` from `better-supabase/realtime`. */",
      `export const topics = ${JSON.stringify(model.meta.topics, null, 2)} as const;`,
      "",
    );
  }
  lines.push(
    "export const schema: Schema<Models, Database, Functions> = defineSchema(meta);",
    "",
  );
  return lines.join("\n");
}
